  interface R extends Base {}
  interface Q extends P1, P2 {}
  interface F extends HasProp {}
  interface Twice extends Base {}
  interface Twice { y: 1 }
  interface InTs extends Base {}
  interface Late { x: number }
  interface G2 extends HasIndex {}
