      test("reports TS2589 for recursive conditional types one step over the depth limit, but not at it", async () => {
        const wrap = `type Wrap<N extends number, T = 1, A extends 1[] = []> = A["length"] extends N ? T : Wrap<N, { v: T }, [...A, 1]>;`;
        // Each entry is the last depth without an error, and the program. Each file has its own types, so none hits
        // another's cached instantiations.
        const shapes: Record<string, [number, (depth: number) => string]> = {
          tail: [
            999,
            depth =>
              `type Count<N extends number, A extends 1[] = []> = A["length"] extends N ? A["length"] : Count<N, [...A, 1]>;\nexport type R = Count<${depth}>;\n`,
          ],
          mapped: [
            48,
            depth =>
              `type Leaves<T> = T extends object ? { [K in keyof T]: Leaves<T[K]> }[keyof T] : T;\n${wrap}\nexport type R = Leaves<Wrap<${depth}>>;\n`,
          ],
          union: [
            49,
            depth =>
              `type Flat<T> = T extends { v: infer V } ? Flat<V> | 0 : T;\n${wrap}\nexport type R = Flat<Wrap<${depth}>>;\n`,
          ],
          tuple: [
            48,
            depth =>
              `type Depth<T> = [T] extends [{ v: infer V }] ? [1, ...Depth<V>] : [];\n${wrap}\nexport type R = Depth<Wrap<${depth}>>;\n`,
          ],
          intersection: [
            49,
            depth =>
              `type All<T> = T extends { v: infer V } ? { d: 1 } & All<V> : {};\n${wrap}\nexport type R = All<Wrap<${depth}>>;\n`,
          ],
        };
        using dir = project(
          Object.fromEntries(
            Object.entries(shapes).flatMap(([name, [last, program]]) => [
              [`${name}-under.ts`, program(last)],
              [`${name}-over.ts`, program(last + 1)],
            ]),
          ),
        );
        const { stdout, exitCode } = await check(dir);
        expect(stdout).toMatchInlineSnapshot(`
          "intersection-over.ts(3,17): error TS5114: Instantiations of type 'All' appear infinitely circular.
          mapped-over.ts(3,17): error TS5114: Instantiations of type 'Leaves' appear infinitely circular.
          tail-over.ts(2,17): error TS2589: Type instantiation is excessively deep and possibly infinite.
          tuple-over.ts(3,17): error TS5114: Instantiations of type 'Depth' appear infinitely circular.
          union-over.ts(3,17): error TS5114: Instantiations of type 'Flat' appear infinitely circular."
        `);
        expect(exitCode).toBe(1);
      });

      test("doesn't instantiate the type of an object literal that has no outer type parameters", async () => {
        // `getObjectTypeInstantiation` returns it as it is, so the nesting doesn't add to the instantiation depth.
        const nested = (leaf: string) => `declare class A<T, K = 1> { a: T; k: K }
declare function box<F>(fields: F): A<F>;
${leaf}
const v0 = box({ p: leaf });
${Array.from({ length: 60 }, (_, i) => `const v${i + 1} = box({ p: v${i} });`).join("\n")}
function pair<U>(u: U) { return { v: v60, u }; }
export const n: never = pair(1).v.k;
`;
        using dir = project({
          // The first branch's `T` is an outer type parameter of the deferred reference in the second branch.
          "deferred.ts": nested(`declare class B<T, K = 1> { b: T; k: K }
type Optional<V> = V extends A<infer T> ? A<T | undefined> : V extends B<infer T> ? B<T | undefined> : never;
declare const leaf: Optional<B<string>>;`),
          "mapped.ts": nested(`type M<T> = { [K in keyof T]: T[K] };
const l1 = { x: 1 }, l2 = { y: 1 };
declare const leaf: M<typeof l1 | typeof l2>;`),
        });
        const { stdout, exitCode } = await check(dir);
        expect(stdout).toMatchInlineSnapshot(`
          "deferred.ts(68,14): error TS2322: Type '1' is not assignable to type 'never'.
          mapped.ts(68,14): error TS2322: Type '1' is not assignable to type 'never'."
        `);
        expect(exitCode).toBe(1);
      });

      test("instantiates a mapped and a conditional type with many different type arguments", async () => {
        const numbers = Array.from({ length: 40 }, (_, i) => i + 10);
        using dir = project({
          "a.ts": `
type Boxes<T> = { [K in keyof T]: { box: T[K] } };
type Named<T> = { [K in keyof T as \`n\${K & string}\`]-?: T[K] };
type First<T> = T extends { p0: infer V } ? V : T extends { p1: infer V } ? [V] : never;
function generic<T>(boxes: Boxes<T>, named: Named<T>, first: First<T>) {
${numbers.map(i => `  boxes = null! as Boxes<T | { p${i}: ${i} }>; named = null! as Named<T & { p${i}: ${i} }>; first = null! as First<T | { p${i % 3}: ${i} }>;`).join("\n")}
}
${numbers.map(i => `const v${i}: never = null! as [Boxes<{ p${i}: ${i} }>["p${i}"], Named<{ p${i}?: ${i} }>["np${i}"], keyof Named<{ p${i}: 1; q: 2 }>, First<{ p${i % 3}: ${i} }>];`).join("\n")}
export {};
`,
        });
        const first = (i: number) => [`${i}`, `[${i}]`, "never"][i % 3];
        const { stdout, exitCode } = await check(dir);
        expect(stdout.split("\n")).toEqual([
          ...numbers.flatMap((i, at) => [
            `a.ts(${at + 6},3): error TS2322: Type 'Boxes<T | { p${i}: ${i}; }>' is not assignable to type 'Boxes<T>'.`,
            `  Type 'Boxes<{ p${i}: ${i}; }>' is not assignable to type 'Boxes<T>'.`,
            ...(i % 3 === 2
              ? []
              : [
                  `a.ts(${at + 6},85): error TS2322: Type '${first(i)} | First<T>' is not assignable to type 'First<T>'.`,
                  `  Type '${i % 3 ? first(i) : "number"}' is not assignable to type 'First<T>'.`,
                ]),
          ]),
          ...numbers.map(
            (i, at) =>
              `a.ts(${at + 47},7): error TS2322: Type '[{ box: ${i}; }, ${i}, "np${i}" | "nq", ${first(i)}]' is not assignable to type 'never'.`,
          ),
        ]);
        expect(exitCode).toBe(1);
      });

