    expect(good.stderr).toContain("1 pass");
    expect(good.exitCode).toBe(0);
    expect(bad.stderr).toContain(`error TS2322: Type 'number' is not assignable to type 'string'.`);
    expect(bad.stderr).not.toContain("1 pass");
